class Account {
    private val lock = ReentrantLock()          // published lock
    private var balance: Long = 0
    val gate: Lock get() = lock

    fun transferTo(to: Account, amount: Long) =
        lock.withLock {                         // release on every path
            to.gate.withLock { balance -= amount; to.balance += amount }
        }
}
